  scope: DriveScope;
  parentId: string | null;
  requestId: string;
  name: string;
  size: number;
  contentType: string;
}
export interface DriveUploadTicket {
  id: string;
  url?: string;
  headers?: Record<string, string>;
  expiresAt?: string;
  completed: boolean;
}
export interface DriveDeletePreview {
  token: string;
  files: number;
  folders: number;
