}

export function DriveToasts({
  labels,
  queue,
}: {
  labels: DriveLabels;
  queue: ReturnType<typeof useUploads>;
}) {
  const { toasts, add, close } = Toast.useToastManager<{ uploads: typeof queue.uploads }>();
  const { uploads, dismiss } = queue;
  const finished = uploads.every((upload) => ["done", "cancelled"].includes(upload.state));
  const loading = uploads.some((upload) =>
    ["queued", "uploading", "finishing", "cancelling"].includes(upload.state),
  );
  useEffect(() => {
    if (!uploads.length) {
      close("drive-uploads");
      return;
    }
    add({
      id: "drive-uploads",
      type: loading ? "loading" : finished ? "success" : "error",
      title: labels.uploads,
      data: { uploads },
      timeout: finished ? 5000 : 0,
      onClose: () => {
        for (const upload of uploads) dismiss(upload.id);
      },
    });
  }, [uploads, finished, loading, labels.uploads, dismiss, add, close]);
  return (
    <Toast.Portal>
      <Toast.Viewport
        aria-label={labels.title}
        className="fixed right-0 bottom-0 z-50 flex max-h-dvh w-full max-w-[26rem] flex-col gap-2 overflow-y-auto p-4 outline-none empty:p-0 sm:right-2 sm:bottom-2 sm:max-h-[calc(100dvh-1rem)]"
      >
        {toasts.map((toast) => (
          <Toast.Root
            key={toast.id}
            toast={toast}
            aria-busy={toast.type === "loading"}
            swipeDirection={toast.data?.uploads && !finished ? [] : undefined}
            onKeyDownCapture={(event) => {
              if (toast.data?.uploads && !finished && event.key === "Escape")
                event.stopPropagation();
            }}
            className="flex flex-col gap-3 rounded-xl bg-popover p-3 text-popover-foreground shadow-lg outline-none focus-visible:ring-2 focus-visible:ring-ring data-ending:opacity-0 data-limited:hidden motion-safe:transition-opacity dark:border dark:border-border dark:shadow-none"
          >
            <div className="flex items-center gap-3">
              {toast.type === "loading" ? (
                <LoaderCircleIcon
                  className="size-5 shrink-0 text-muted-foreground motion-safe:animate-spin"
                  aria-hidden="true"
                />
              ) : toast.type === "success" ? (
                <CircleCheckIcon
                  className="size-5 shrink-0 text-status-success-foreground"
                  aria-hidden="true"
                />
              ) : toast.type === "error" ? (
                <CircleAlertIcon className="size-5 shrink-0 text-destructive" aria-hidden="true" />
              ) : (
                <DownloadIcon
                  className="size-5 shrink-0 text-status-info-foreground"
                  aria-hidden="true"
                />
              )}
              <div className="min-w-0 flex-1">
                <Toast.Title className="text-sm break-words" />
                <Toast.Description className="mt-1 text-sm break-words text-muted-foreground" />
              </div>
              <Toast.Action
                className={cn(outlineButtonClass, "shrink-0")}
                disabled={toast.actionProps?.disabled}
              />
              {(!toast.data?.uploads || finished) && (
                <IconTooltip label={labels.close}>
                  <Toast.Close
                    aria-label={labels.close}
                    aria-hidden={false}
                    className={cn(buttonClass, "size-10 shrink-0 p-0 md:size-8")}
                  >
                    <XIcon aria-hidden="true" />
                  </Toast.Close>
                </IconTooltip>
              )}
            </div>
            {toast.data?.uploads && (
              <ul className="ms-8 max-h-[50dvh] space-y-4 overflow-y-auto">
                {toast.data.uploads.map((upload) => (
                  <li key={upload.id} className="space-y-2">
                    <span className="block text-sm break-all">{upload.file.name}</span>
                    <progress
                      className="h-2 w-full accent-primary"
                      max={100}
                      value={upload.progress}
                      aria-label={labels.progress(upload.file.name)}
                    />
                    <DriveFeedback
                      message={labels[upload.state]}
                      error={upload.state === "failed" || upload.state === "cancelFailed"}
                    />
                    {upload.error !== undefined && (
                      <DriveFeedback message={messageFor(upload.error, labels)} error />
                    )}
                    <div className="flex flex-wrap gap-2">
                      {["failed", "cancelFailed"].includes(upload.state) && (
                        <button className={buttonClass} onClick={() => queue.retry(upload.id)}>
                          <RefreshCwIcon className="size-4 shrink-0" aria-hidden="true" />
                          {labels.retry}
                        </button>
                      )}
                      {["queued", "uploading", "failed"].includes(upload.state) && (
                        <button className={buttonClass} onClick={() => queue.cancel(upload.id)}>
                          {labels.cancel}
                        </button>
                      )}
                      {["done", "cancelled"].includes(upload.state) && (
                        <button className={buttonClass} onClick={() => dismiss(upload.id)}>
                          {labels.dismiss}
                        </button>
                      )}
                    </div>
                  </li>
                ))}
              </ul>
            )}
          </Toast.Root>
        ))}
      </Toast.Viewport>
    </Toast.Portal>
  );
}

export function EntryDialog({
  client,
  scope,
  parentId,
  entry,
  space,
  onRenameSpace,
  menu = false,
  deleting = false,
  trashing = false,
  disabled = false,
  labels,
  refresh,
  children,
}: {
  client: DriveClient;
  scope: DriveScope;
  parentId: string | null;
  entry?: Pick<DriveEntry, "id" | "name">;
  space?: DriveSpace;
  onRenameSpace?: DriveBrowserProps["onRenameSpace"];
  menu?: boolean;
  deleting?: boolean;
  trashing?: boolean;
  disabled?: boolean;
  labels: DriveLabels;
  refresh: () => void;
  children?: ReactNode;
}) {
  const [open, setOpen] = useState(false);
  const [name, setName] = useState(entry?.name ?? space?.name ?? "");
  const menuTrigger = useRef<HTMLButtonElement>(null);
  const [pending, setPending] = useState(false);
  const [previewLoading, setPreviewLoading] = useState(false);
  const [error, setError] = useState<string>();
  const [preview, setPreview] = useState<DriveDeletePreview>();
  const previewRequest = useRef<Promise<DriveDeletePreview> | undefined>(undefined);
  const lock = useRef(false);
  const fieldId = `factory-drive-field-${useId()}`;
  const title = deleting
    ? trashing
      ? labels.trashTitle
      : labels.deleteTitle
    : entry || space
      ? labels.rename
      : labels.newFolder;
  function loadPreview() {
    if (disabled || !entry) return;
    setPreviewLoading(true);
    setError(undefined);
    setPreview(undefined);
    const request = Promise.resolve().then(() =>
      client.previewDelete({ scope, entryId: entry.id }),
    );
    previewRequest.current = request;
    void request.then(
      (result) => {
        if (previewRequest.current !== request) return;
        setPreview(result);
        setPreviewLoading(false);
      },
      (reason) => {
        if (previewRequest.current !== request) return;
        previewRequest.current = undefined;
        setError(messageFor(reason, labels));
        setPreviewLoading(false);
      },
    );
    return request;
  }
  async function submit() {
    if (disabled || lock.current) return;
    lock.current = true;
    setPending(true);
    setError(undefined);
    try {
      if (deleting && entry) {
        const confirmation = preview ?? (await (previewRequest.current ?? loadPreview()));
        if (!confirmation) return;
        if (trashing)
          await client.trashEntry!({ scope, entryId: entry.id, token: confirmation.token });
        else await client.deleteEntry({ scope, entryId: entry.id, token: confirmation.token });
      } else if (entry) await client.rename({ scope, entryId: entry.id, name: validName(name) });
      else if (space && onRenameSpace) await onRenameSpace(validName(name));
      else await client.createFolder({ scope, parentId, name: validName(name) });
      setOpen(false);
      refresh();
    } catch (reason) {
      setError(messageFor(reason, labels));
      if (deleting && errorCode(reason) === "CONFLICT") {
        setPreview(undefined);
        previewRequest.current = undefined;
      }
    } finally {
      lock.current = false;
      setPending(false);
    }
  }
  function changeOpen(next: boolean) {
    if (lock.current) return;
    setOpen(next);
    if (next) {
      setName(entry?.name ?? space?.name ?? "");
      setError(undefined);
      if (deleting) void loadPreview();
    } else {
      previewRequest.current = undefined;
      setPreviewLoading(false);
    }
  }
  return (
    <Dialog.Root open={open} onOpenChange={changeOpen}>
      {menu ? (
        <DropdownMenu>
          <IconTooltip label={`${labels.actions}: ${entry?.name ?? space?.name}`}>
            <DropdownMenuTrigger
              ref={menuTrigger}
              disabled={disabled}
              className={cn(buttonClass, "size-10 shrink-0 p-0 md:size-8")}
              aria-label={`${labels.actions}: ${entry?.name ?? space?.name}`}
            >
              <ChevronDownIcon className="size-4 shrink-0" aria-hidden="true" />
            </DropdownMenuTrigger>
          </IconTooltip>
          <DropdownMenuContent className="min-w-40 rounded-xl motion-reduce:animate-none">
            <DropdownMenuItem onClick={() => changeOpen(true)} className="min-h-10 rounded-md">
              <PencilIcon className="size-4 shrink-0" aria-hidden="true" />
              {labels.rename}
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      ) : (
        <IconTooltip label={entry ? (deleting ? labels.delete : labels.rename) : undefined}>
          <Dialog.Trigger
            disabled={disabled}
            className={cn(
              entry ? iconButtonClass : buttonClass,
              deleting &&
                "bg-destructive/10 text-destructive hover:bg-destructive/20 hover:text-destructive focus-visible:ring-destructive/30 dark:bg-destructive/20 dark:hover:bg-destructive/30",
            )}
            aria-label={deleting ? labels.delete : entry ? labels.rename : labels.newFolder}
          >
            {children}
          </Dialog.Trigger>
        </IconTooltip>
      )}
      <Dialog.Portal>
        <Dialog.Backdrop className="fixed inset-0 z-50 bg-foreground/30" />
        <Dialog.Popup
          finalFocus={menu ? menuTrigger : undefined}
          onKeyDownCapture={deleting ? undefined : submitDialogOnShortcut}
          className={cn(
            cardClass,
            "fixed top-1/2 left-1/2 z-50 w-[calc(100%-2rem)] max-w-md -translate-x-1/2 -translate-y-1/2 space-y-5 shadow-xl",
          )}
        >
          <Dialog.Title className="text-lg font-semibold">{title}</Dialog.Title>
          <Dialog.Description
            className={cn("text-sm text-muted-foreground", deleting && "min-h-20")}
          >
            {deleting
              ? preview && entry
                ? (trashing ? labels.trashDescription : labels.deleteDescription)(
                    entry.name,
                    preview.files,
                    preview.folders,
                  )
                : entry
                  ? (trashing ? labels.trashConfirmation : labels.deleteConfirmation)(entry.name)
                  : labels.loading
              : labels.nameHint}
          </Dialog.Description>
          <form
            onSubmit={(event) => {
              event.preventDefault();
              void submit();
            }}
            className="space-y-4"
          >
            {!deleting && (
              <div className="space-y-2">
                <label htmlFor={fieldId} className="text-sm font-medium">
                  {labels.name}
                </label>
                <input
                  id={fieldId}
                  className={inputClass}
                  value={name}
                  onChange={(event) => setName(event.target.value)}
                  maxLength={255}
                  required
                  disabled={pending || disabled}
                />
              </div>
            )}
            <div className={deleting ? "min-h-5" : undefined}>
              <DriveFeedback
                message={
                  error ??
                  (deleting && (pending || previewLoading)
                    ? pending
                      ? labels.pending
                      : labels.loading
                    : undefined)
                }
                error={Boolean(error)}
              />
            </div>
            <div className="flex flex-wrap justify-end gap-2">
              <Dialog.Close className={outlineButtonClass} disabled={pending}>
                {labels.cancel}
              </Dialog.Close>
              <button
                type="submit"
                className={cn(
                  primaryClass,
                  deleting &&
                    "bg-destructive/10 text-destructive hover:bg-destructive/20 hover:text-destructive focus-visible:ring-destructive/30 dark:bg-destructive/20 dark:hover:bg-destructive/30",
                )}
                disabled={pending || disabled}
              >
                {pending && !deleting
                  ? labels.pending
                  : deleting
                    ? trashing
                      ? labels.moveToTrash
                      : labels.confirmDelete
                    : entry || space
                      ? labels.save
                      : labels.create}
              </button>
            </div>
          </form>
        </Dialog.Popup>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

import type { DriveTransfer } from "@/components/plugins/drive/transfer";
import { transferDriveUpload } from "@/components/plugins/drive/transfer";
import type { DriveClient, DriveScope } from "@/components/plugins/drive/types";
import { DriveError, errorCode } from "@/components/plugins/drive/utils";

type State =
  | "queued"
  | "uploading"
  | "finishing"
  | "done"
  | "failed"
  | "cancelled"
  | "cancelling"
  | "cancelFailed";
interface Job {
  id: string;
  file: File;
  state: State;
  progress: number;
  error?: unknown;
  controller: AbortController;
  reserved: boolean;
  busy: boolean;
  cancelled: boolean;
}
export function useUploads(
  client: DriveClient,
  scope: DriveScope,
  parentId: string | null,
  refresh: () => void,
  transfer: DriveTransfer = transferDriveUpload,
) {
  const jobs = useRef<Job[]>([]);
  const mounted = useRef(true);
  const [uploads, setUploads] = useState<Job[]>([]);
  const publish = useCallback(() => {
    if (mounted.current) setUploads(jobs.current.map((job) => ({ ...job })));
  }, []);
  const dismiss = useCallback(
    (id: string) => {
      jobs.current = jobs.current.filter(
        (job) => job.id !== id || !["done", "cancelled"].includes(job.state),
      );
      publish();
    },
    [publish],
  );
  async function abandon(job: Job) {
    job.state = "cancelling";
    publish();
    try {
      if (job.reserved) await client.cancelUpload({ scope, uploadId: job.id });
      job.state = "cancelled";
    } catch (error) {
      job.state = errorCode(error) === "NOT_FOUND" ? "cancelled" : "cancelFailed";
      job.error = job.state === "cancelled" ? undefined : error;
    }
    publish();
  }
  async function run(job: Job) {
    job.busy = true;
    job.state = "uploading";
    job.error = undefined;
    publish();
    try {
      // Mark before preparation: a lost preparation response may still reserve a file.
      job.reserved = true;
      const ticket = await client.prepareUpload({
        scope,
        parentId,
        requestId: job.id,
        name: job.file.name,
        size: job.file.size,
        contentType: job.file.type,
      });
      if (job.cancelled) {
        await abandon(job);
        return;
      }
      if (!ticket.completed) {
        try {
          await transfer(ticket, job.file, {
            signal: job.controller.signal,
            onProgress: (value) => {
              job.progress = value;
              publish();
            },
          });
        } catch (error) {
          if (job.cancelled) throw error;
          // A dropped PUT response is uncertain; the server can verify whether it arrived.
          job.state = "finishing";
          publish();
          await client.completeUpload({ scope, uploadId: job.id });
          job.state = "done";
          job.progress = 100;
          if (mounted.current) refresh();
          return;
        }
        if (job.cancelled) {
          await abandon(job);
          return;
        }
        job.state = "finishing";
        publish();
        await client.completeUpload({ scope, uploadId: job.id });
      }
      job.state = "done";
      job.progress = 100;
      if (mounted.current) refresh();
    } catch (error) {
      if (job.cancelled) await abandon(job);
      else {
        job.state = "failed";
        job.error = error;
      }
    } finally {
      job.busy = false;
      publish();
      pump();
    }
  }
  function pump() {
    if (!mounted.current) return;
    let active = jobs.current.filter((job) => job.busy).length;
    for (const job of jobs.current) {
      if (active >= 2) break;
      if (job.state === "queued") {
        active++;
        void run(job);
      }
    }
  }
  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
      for (const job of jobs.current) {
        if (["done", "cancelled"].includes(job.state)) continue;
        job.cancelled = true;
        job.controller.abort();
        if (!job.busy) void abandon(job);
      }
    };
    // This hook is owned by a browser keyed to its space and folder.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  return {
    uploads,
    add(files: File[], maxBytes: number) {
      for (const file of files)
        jobs.current.push({
          id: crypto.randomUUID(),
          file,
          state: file.size > maxBytes ? "failed" : "queued",
          error: file.size > maxBytes ? new DriveError("INVALID") : undefined,
          progress: 0,
          controller: new AbortController(),
          reserved: false,
          busy: false,
          cancelled: false,
        });
      publish();
      pump();
    },
    cancel(id: string) {
      const job = jobs.current.find((item) => item.id === id);
      if (!job || job.state === "finishing" || job.state === "done") return;
      job.cancelled = true;
      job.controller.abort();
      if (!job.busy) void abandon(job);
      else {
        job.state = "cancelling";
        publish();
      }
    },
    retry(id: string) {
      const job = jobs.current.find((item) => item.id === id);
      if (!job || job.busy) return;
      if (job.state === "cancelFailed") {
        void abandon(job);
        return;
      }
      if (job.state !== "failed") return;
      job.controller = new AbortController();
      job.cancelled = false;
      job.state = "queued";
      job.progress = 0;
      publish();
      pump();
    },
    dismiss,
  };
}

import type { DriveScope, DriveSort, DriveSpace } from "@/components/plugins/drive/types";
export const DEFAULT_MAX_FILE_BYTES = 100_000_000;
export const scopeKey = (scope: DriveScope) => JSON.stringify([scope.type, scope.id]);
export type DriveErrorCode =
  | "INVALID"
  | "NOT_FOUND"
  | "FORBIDDEN"
  | "CONFLICT"
  | "RESTORE_CONFLICT"
  | "EXPIRED"
  | "DELETE_PENDING"
  | "STORAGE";
export class DriveError extends Error {
  readonly code: DriveErrorCode;
  constructor(code: DriveErrorCode) {
    super(code);
    this.name = "DriveError";
    this.code = code;
  }
}
export function validName(input: string) {
  if (typeof input !== "string") throw new DriveError("INVALID");
  const name = input.trim();
  if (
    !name ||
    name.length > 255 ||
    name === "." ||
    name === ".." ||
    /[/\\]/.test(name) ||
    name.split("").some((char) => char.charCodeAt(0) < 32 || char.charCodeAt(0) === 127)
  )
    throw new DriveError("INVALID");
  return name;
}
export function validScope(scope: DriveScope) {
  if (
    !scope ||
    typeof scope.type !== "string" ||
    typeof scope.id !== "string" ||
    !scope.type.trim() ||
    !scope.id.trim() ||
    scope.type.length > 100 ||
    scope.id.length > 512
  )
    throw new DriveError("INVALID");
  return scope;
}
export function validId(id: string) {
  if (
    typeof id !== "string" ||
    !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id)
  )
    throw new DriveError("INVALID");
  return id;
}
export function errorCode(error: unknown): DriveErrorCode | undefined {
  if (
    error &&
    typeof error === "object" &&
    "code" in error &&
    typeof error.code === "string" &&
    [
      "INVALID",
      "NOT_FOUND",
      "FORBIDDEN",
      "CONFLICT",
      "RESTORE_CONFLICT",
      "EXPIRED",
      "DELETE_PENDING",
      "STORAGE",
    ].includes(error.code)
  )
    return error.code as DriveErrorCode;
}
export function safeDownloadUrl(input: string) {
  try {
    const url = new URL(input);
    return ["http:", "https:", "blob:"].includes(url.protocol) && !url.username && !url.password
      ? input
      : undefined;
  } catch {
    return undefined;
  }
}

export function validSort(sort: DriveSort = { field: "name", direction: "asc" }): DriveSort {
  if (
    !sort ||
    !["name", "updatedAt", "size", "owner"].includes(sort.field) ||
    !["asc", "desc"].includes(sort.direction)
  )
    throw new DriveError("INVALID");
  return sort;
}

/** Compare metadata before pagination; missing values sort last in either direction. */
export function compareDriveItems(
  a: Pick<DriveSpace, "name" | "updatedAt" | "size" | "owner">,
  b: Pick<DriveSpace, "name" | "updatedAt" | "size" | "owner">,
  sort: DriveSort,
) {
  const value = (item: typeof a) => {
    if (sort.field === "owner") return item.owner?.name;
    if (sort.field === "updatedAt") {
      const time = item.updatedAt ? Date.parse(item.updatedAt) : NaN;
      return Number.isFinite(time) ? time : undefined;
    }
    return item[sort.field];
  };
  const left = value(a);
  const right = value(b);
  if (left === undefined && right !== undefined) return 1;
  if (right === undefined && left !== undefined) return -1;
  const order =
    typeof left === "number" && typeof right === "number"
      ? left - right
      : String(left ?? "").localeCompare(String(right ?? ""));
  return order * (sort.direction === "asc" ? 1 : -1) || a.name.localeCompare(b.name);
}

"use client";

import { Dialog } from "@base-ui/react/dialog";
import { Toast } from "@base-ui/react/toast";
import { RefreshCwIcon, RotateCcwIcon, Trash2Icon } from "lucide-react";
import { useEffect, useId, useMemo, useRef, useState } from "react";

import { NativeSelect } from "@/components/native-select";
import type { DriveLabels } from "@/components/plugins/drive/labels";
import type {
  DriveClient,
  DriveFolderResult,
  DriveScope,
  DriveTrashEntry,
  DriveTrashResult,
} from "@/components/plugins/drive/types";
import {
  buttonClass,
  cardClass,
  DriveFeedback,
  DriveModified,
  EntryDialog,
  inputClass,
  messageFor,
  outlineButtonClass,
  primaryClass,
} from "@/components/plugins/drive/ui";
import { errorCode, validName } from "@/components/plugins/drive/utils";
import { TablePagination } from "@/components/table-pagination";
import { TableSearch } from "@/components/table-search";
import { cn } from "@/components/utils/cn";
import { submitDialogOnShortcut } from "@/components/utils/dialog-submit";
import {
  tableActionCellClass,
  tableCellClass,
  tableClass,
  tableHeaderClass,
  tablePanelClass,
  tableRowClass,
} from "@/components/utils/table-styles";
import { retainRemovedItems, useOptimisticAction } from "@/components/utils/use-optimistic-action";

export function TrashBrowser({
  client,
  scope,
  labels,
  locale,
  refreshKey = 0,
  onChanged,
}: {
  client: DriveClient;
  scope: DriveScope;
  labels: DriveLabels;
  locale?: string;
  refreshKey?: number;
  onChanged?: () => void;
}) {
  const [search, setSearch] = useState("");
  const [cursors, setCursors] = useState<string[]>([]);
  const cursor = cursors.at(-1);
  const [revision, setRevision] = useState(0);
  const request = useMemo(
    () => ({ client, scope, search, cursor, revision, refreshKey }),
    [client, scope, search, cursor, revision, refreshKey],
  );
  const [result, setResult] = useState<{
    request: typeof request;
    data?: DriveTrashResult;
    error?: unknown;
    now?: number;
  }>();
  const [restoring, setRestoring] = useState<string>();
  const [restoreEntry, setRestoreEntry] = useState<DriveTrashEntry>();
  const lock = useRef(false);
  const manager = Toast.useToastManager();
  const loading = result?.request !== request;
  const mutationScope = useMemo(
    () => ({ client, scope, search, cursor }),
    [client, scope, search, cursor],
  );
  const optimistic = useOptimisticAction(result?.data, mutationScope);
  const data = optimistic.value;
  const error = loading ? undefined : result?.error;
  const disabled = loading || !!error || !!restoring || optimistic.pending;
  const refresh = () => setRevision((value) => value + 1);
  const restored = () => {
    setRestoreEntry(undefined);
    refresh();
    onChanged?.();
    manager.add({ title: labels.restored, type: "success" });
  };
  useEffect(() => {
    const controller = new AbortController();
    void client.listTrash!({
      scope: request.scope,
      search: request.search,
      cursor: request.cursor,
      signal: controller.signal,
    })
      .then((data) => {
        if (!controller.signal.aborted) setResult({ request, data, now: Date.now() });
      })
      .catch((error: unknown) => {
        if (!controller.signal.aborted) setResult({ request, error });
      });
    return () => controller.abort();
  }, [client, request]);
  async function restore(entry: DriveTrashEntry) {
    if (disabled || lock.current) return;
    lock.current = true;
    setRestoring(entry.id);
    try {
      await optimistic.run(
        (current) =>
          current && { ...current, items: current.items.filter((row) => row.id !== entry.id) },
        () => client.restoreEntry!({ scope, entryId: entry.id }),
      );
      restored();
    } catch (reason) {
      if (errorCode(reason) === "RESTORE_CONFLICT") setRestoreEntry(entry);
      else manager.add({ title: messageFor(reason, labels), type: "error" });
    } finally {
      lock.current = false;
      setRestoring(undefined);
    }
  }
  return (
    <>
      <DriveFeedback
        message={optimistic.error ? messageFor(optimistic.error, labels) : undefined}
        error
      />
      <div className="flex flex-wrap justify-end gap-2">
        <TableSearch
          value={search}
          label={labels.searchTrash}
          clearLabel={labels.clearSearch}
          onValueChange={(value) => {
            setSearch(value);
            setCursors([]);
          }}
        />
        <button className={buttonClass} disabled={loading} onClick={refresh}>
          <RefreshCwIcon className="size-4 shrink-0" aria-hidden="true" />
          {labels.retry}
        </button>
      </div>
      <div className={tablePanelClass} aria-busy={loading}>
        <p className="mb-4 text-sm text-muted-foreground">{labels.trashHint}</p>
        <div className="overflow-x-auto">
          <table className={cn(tableClass, "min-w-[44rem]")} aria-label={labels.trash}>
            <thead>
              <tr className={tableRowClass}>
                {[
                  labels.name,
                  labels.originalLocation,
                  labels.deletedAt,
                  labels.expiresAt,
                  labels.actions,
                ].map((label, index) => (
                  <th
                    key={index}
                    scope="col"
                    className={index === 4 ? tableActionCellClass : tableHeaderClass}
                  >
                    {label}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody className="[&_tr:last-child]:border-0">
              {(!!error || !data?.items.length) && (
                <tr>
                  <td colSpan={5} className={cn(tableCellClass, "py-8")}>
                    <DriveFeedback
                      message={
                        error
                          ? messageFor(error, labels)
                          : loading
                            ? labels.loading
                            : search
                              ? labels.noMatches
                              : labels.emptyTrash
                      }
                      error={!!error}
                    />
                  </td>
                </tr>
              )}
              {data &&
                retainRemovedItems(data.items, result?.data?.items ?? [], optimistic.pending).map(
                  (entry) => (
                    <tr
                      key={entry.id}
                      hidden={!data.items.some((row) => row.id === entry.id)}
                      className={tableRowClass}
                    >
                      <td className={cn(tableCellClass, "max-w-64 break-all")}>
                        {entry.name}
                        {entry.state === "deleting" && (
                          <output className="mt-1 block text-xs text-muted-foreground">
                            {labels.deleting}
                          </output>
                        )}
                      </td>
                      <td
                        className={cn(tableCellClass, "max-w-64 break-all text-muted-foreground")}
                      >
                        {entry.originalPath || labels.root}
                      </td>
                      <td className={cn(tableCellClass, "whitespace-nowrap text-muted-foreground")}>
                        <DriveModified
                          value={entry.deletedAt}
                          locale={locale}
                          fallback={labels.unavailable}
                        />
                      </td>
                      <td className={cn(tableCellClass, "whitespace-nowrap text-muted-foreground")}>
                        <DriveModified
                          value={entry.expiresAt}
                          locale={locale}
                          fallback={labels.unavailable}
                        />
                      </td>
                      <td className={tableActionCellClass}>
                        <div className="flex justify-end gap-2">
                          {data.space.capabilities.restore && entry.state === "trashed" && (
                            <button
                              className={buttonClass}
                              disabled={
                                disabled || Date.parse(entry.expiresAt) <= (result?.now ?? 0)
                              }
                              onClick={() => void restore(entry)}
                            >
                              <RotateCcwIcon aria-hidden="true" />
                              {restoring === entry.id ? labels.pending : labels.restore}
                            </button>
                          )}
                          {data.space.capabilities.delete && (
                            <EntryDialog
                              client={{
                                ...client,
                                deleteEntry: (input) =>
                                  optimistic.run(
                                    (current) =>
                                      current && {
                                        ...current,
                                        items: current.items.filter(
                                          (row) => row.id !== input.entryId,
                                        ),
                                      },
                                    () => client.deleteEntry(input),
                                  ),
                              }}
                              scope={scope}
                              parentId={null}
                              entry={entry}
                              deleting
                              disabled={disabled}
                              labels={labels}
                              refresh={() => {
                                refresh();
                                manager.add({ title: labels.deleted, type: "success" });
                              }}
                            >
                              <Trash2Icon className="size-4 shrink-0" aria-hidden="true" />
                            </EntryDialog>
                          )}
                        </div>
                      </td>
                    </tr>
                  ),
                )}
            </tbody>
          </table>
        </div>
        <TablePagination
          label={labels.title}
          page={cursors.length + 1}
          previousLabel={labels.previous}
          nextLabel={labels.next}
          previousDisabled={cursors.length === 0}
          nextDisabled={!!error || !data?.nextCursor}
          disabled={loading}
          onPrevious={() => setCursors(cursors.slice(0, -1))}
          onNext={() => {
            if (data?.nextCursor) setCursors([...cursors, data.nextCursor]);
          }}
        />
      </div>
      {restoreEntry && (
        <RestoreDialog
          client={client}
          scope={scope}
          entry={restoreEntry}
          labels={labels}
          canRename={!!data?.space.capabilities.rename}
          disabled={disabled}
          close={() => setRestoreEntry(undefined)}
          restored={restored}
          onRestore={(input) =>
            optimistic.run(
              (current) =>
                current && {
                  ...current,
                  items: current.items.filter((row) => row.id !== input.entryId),
                },
              () => client.restoreEntry!(input),
            )
          }
        />
      )}
    </>
  );
}

function RestoreDialog({
  client,
  scope,
  entry,
  labels,
  canRename,
  disabled,
  close,
  restored,
  onRestore,
}: {
  client: DriveClient;
  scope: DriveScope;
  entry: DriveTrashEntry;
  labels: DriveLabels;
  canRename: boolean;
  disabled: boolean;
  close: () => void;
  restored: () => void;
  onRestore: NonNullable<DriveClient["restoreEntry"]>;
}) {
  const [name, setName] = useState(entry.name);
  const [destination, setDestination] = useState<string | null>();
  const [cursors, setCursors] = useState<string[]>([]);
  const cursor = cursors.at(-1);
  const [pending, setPending] = useState(false);
  const [error, setError] = useState<string>(labels.RESTORE_CONFLICT);
  const [revision, setRevision] = useState(0);
  const request = useMemo(
    () => ({ client, scope, destination, cursor, revision }),
    [client, scope, destination, cursor, revision],
  );
  const [result, setResult] = useState<{
    request: typeof request;
    data?: DriveFolderResult;
    error?: string;
  }>();
  const folder = result?.data;
  const loading = result?.request !== request;
  const folderError = loading ? undefined : result?.error;
  const lock = useRef(false);
  const fieldId = `factory-drive-restore-${useId()}`;
  useEffect(() => {
    const controller = new AbortController();
    void client
      .listEntries({ scope, parentId: destination ?? null, cursor, signal: controller.signal })
      .then((data) => {
        if (!controller.signal.aborted) {
          setResult({ request, data });
        }
      })
      .catch((reason: unknown) => {
        if (!controller.signal.aborted) {
          setResult({ request, error: messageFor(reason, labels) });
        }
      });
    return () => controller.abort();
  }, [client, scope, destination, cursor, request, labels]);
  async function submit() {
    if (disabled || lock.current) return;
    lock.current = true;
    setPending(true);
    setError("");
    try {
      await onRestore({
        scope,
        entryId: entry.id,
        parentId: destination,
        name: validName(name),
      });
      restored();
    } catch (reason) {
      setError(messageFor(reason, labels));
    } finally {
      lock.current = false;
      setPending(false);
    }
  }
  return (
    <Dialog.Root
      open
      onOpenChange={(open) => {
        if (!open && !lock.current) close();
      }}
    >
      <Dialog.Portal>
        <Dialog.Backdrop className="fixed inset-0 z-50 bg-foreground/30" />
        <Dialog.Popup
          onKeyDownCapture={submitDialogOnShortcut}
          className={cn(
            cardClass,
            "fixed top-1/2 left-1/2 z-50 max-h-[calc(100dvh-2rem)] w-[calc(100%-2rem)] max-w-md -translate-x-1/2 -translate-y-1/2 space-y-5 overflow-y-auto shadow-xl",
          )}
        >
          <Dialog.Title className="text-lg font-semibold">{labels.restoreTitle}</Dialog.Title>
          <Dialog.Description className="text-sm text-muted-foreground">
            {labels.restoreDescription}
          </Dialog.Description>
          <form
            className="space-y-4"
            onSubmit={(event) => {
              event.preventDefault();
              void submit();
            }}
          >
            <div className="space-y-2">
              <label htmlFor={fieldId} className="text-sm font-medium">
                {labels.name}
              </label>
              <input
                id={fieldId}
                className={inputClass}
                value={name}
                onChange={(event) => setName(event.target.value)}
                required
                maxLength={255}
                disabled={pending || disabled || !canRename}
              />
            </div>
            <div className="space-y-2">
              <label htmlFor={`${fieldId}-folder`} className="text-sm font-medium">
                {labels.destination}
              </label>
              <NativeSelect
                id={`${fieldId}-folder`}
                className={inputClass}
                value={destination === undefined ? "original" : (destination ?? "root")}
                disabled={pending || disabled || loading}
                onChange={(event) => {
                  setDestination(
                    event.target.value === "original"
                      ? undefined
                      : event.target.value === "root"
                        ? null
                        : event.target.value,
                  );
                  setCursors([]);
                }}
              >
                <option value="original">
                  {labels.originalFolder}: {entry.originalPath || labels.root}
                </option>
                <option value="root">{labels.root}</option>
                {folder?.breadcrumbs.map((row) => (
                  <option key={row.id} value={row.id}>
                    {row.name}
                  </option>
                ))}
                {folder?.items
                  .filter((row) => row.kind === "folder" && row.state === "ready")
                  .map((row) => (
                    <option key={row.id} value={row.id}>
                      {row.name}
                    </option>
                  ))}
              </NativeSelect>
              <div className="min-h-10">
                <DriveFeedback
                  message={loading ? labels.loading : folderError}
                  error={!!folderError}
                />
              </div>
              <div className="flex flex-wrap gap-2">
                <TablePagination
                  className="mt-0"
                  label={labels.destination}
                  page={cursors.length + 1}
                  previousLabel={labels.previous}
                  nextLabel={labels.next}
                  previousDisabled={cursors.length === 0}
                  nextDisabled={!folder?.nextCursor || !!folderError}
                  disabled={loading || pending}
                  onPrevious={() => setCursors(cursors.slice(0, -1))}
                  onNext={() => {
                    if (folder?.nextCursor) setCursors([...cursors, folder.nextCursor]);
                  }}
                />
                {folderError && (
                  <button
                    type="button"
                    className={buttonClass}
                    onClick={() => setRevision((value) => value + 1)}
                  >
                    <RefreshCwIcon aria-hidden="true" />
                    {labels.retry}
                  </button>
                )}
              </div>
            </div>
            <div className="min-h-15 md:min-h-10">
              <DriveFeedback message={error} error />
            </div>
            <div className="flex flex-wrap justify-end gap-2">
              <Dialog.Close className={outlineButtonClass} disabled={pending}>
                {labels.cancel}
              </Dialog.Close>
              <button
                type="submit"
                className={primaryClass}
                disabled={pending || disabled || loading || !!folderError}
              >
                {pending ? labels.pending : labels.restore}
              </button>
            </div>
          </form>
        </Dialog.Popup>
      </Dialog.Portal>
    </Dialog.Root>
  );
}
